const input=$json.body??$json;
const route=String(input.route??input.status??'').toLowerCase();
const contractPrice=Number(input.proposed_contract_price??input.contract_price??input.accepted_price??0);
const mao=Number(input.dynamic_mao??input.adjusted_mao??input.mao??0);
const leadId=input.lead_id, dealId=input.deal_id, propertyId=input.property_id;
const sellerName=String(input.seller_name??input.owner_name??'').trim();
const sellerContact=String(input.seller_phone??input.seller_email??input.recipient??'').trim();
const agreementType=String(input.agreement_type??'purchase_agreement').trim();
const signatureProvider=String(input.signature_provider??'').trim();
const dnc=input.dnc===true||route==='blocked_dnc';
const blockers=Array.isArray(input.blockers)?input.blockers:[];
let status='needs_review',next='WF-126',reason='contract package requires review';
const identityReady=Boolean(leadId&&dealId&&propertyId&&sellerName&&sellerContact);
const priceProtected=mao>0&&contractPrice>0&&contractPrice<=mao;
if(dnc){status='blocked_dnc';next='WF-126';reason='DNC/contact restriction';}
else if(blockers.length){status='blocked';next='WF-126';reason='active blockers prevent contract launch';}
else if(!identityReady){status='incomplete_identity';next='WF-126';reason='seller/deal/property identity incomplete';}
else if(!contractPrice){status='missing_contract_price';next='WF-126';reason='contract price missing';}
else if(!priceProtected){status='above_mao';next='WF-126';reason='contract price exceeds protected dynamic MAO';}
else if(!signatureProvider){status='signature_provider_required';next='WF-126';reason='signature provider/runtime configuration required';}
else if(route==='contract_trigger'){status='signature_ready';next='WF-322';reason='contract package validated and ready for signature launch';}
else if(route==='revised_offer_followup'){status='revised_offer_not_contract_ready';next='WF-315';reason='revised offer must be dispatched before contract launch';}
else {status='needs_review';next='WF-126';reason='route is not contract-ready';}
return [{json:{...input,workflow_id:'WF-321',workflow_name:'Contract Trigger → Contract Package Validation & Signature Launch Controller',status,reason,contract_price:contractPrice||null,dynamic_mao:mao||null,agreement_type:agreementType,seller:{name:sellerName,contact:sellerContact},signature_provider:signatureProvider||null,identity_ready:identityReady,price_protected:priceProtected,next_workflow:next,human_review_required:true,crm_activity:{activity_type:'contract_package_validation',deal_id:dealId,lead_id:leadId,property_id:propertyId,status,contract_price:contractPrice||null,agreement_type:agreementType,reason}}}];
